mapper.select:
SELECT distinct a.id, a.project_id, a.monomer_id, a.area_id, a.area_batch_id, 2 product_type, a.bool_status_enum, a.bool_abnormal_enum abnormal, a.structure_type, a.name, a.serial_number, a.specification, a.length, a.material, a.quantity, a.total_net_weight, a.total_gross_weight, a.net_weight, a.gross_weight, a.surface_area / 1000000 surface_area, a.surface_area * a.quantity / 1000000 totalSurfaceArea, a.top_flange_area / 1000000 as top_flange_area, a.drawing_number, a.remark, a.user_id, a.business_id, a.produced_quantity, a.area_type, a.smart_line_mark_word, a.artifact_type, a.production_line_type_enum, a.bool_blasting_enum, a.bool_coating_enum, a.bool_scheduling_enum, a.coding_type, a.structure_class_id, a.create_time, a.drawing_weight, a.total_drawing_weight, a.bool_send_directly, u.name as user_name, 1 has_machine_part, a.printed_code FROM tech_artifact AS a LEFT JOIN sys_user AS u ON a.user_id = u.id AND u.bool_delete_enum = 0
INNER JOIN sys_monomer_user_link AS link ON a.monomer_id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}
INNER JOIN ( SELECT DISTINCT link.artifact_id FROM tech_artifact_machine_part_link AS link INNER JOIN tech_machine_part AS m ON m.id = link.machine_part_id WHERE link.bool_delete_enum = 0 AND m.bool_delete_enum = 0
AND m.area_id = #{areaId}
AND m.area_batch_id = #{areaBatchId}
AND m.relation_type in (2 ) AND m.serial_number like concat('%',#{machinePartSerialNumber},'%') ) AS ids ON a.id = ids.artifact_id
INNER JOIN ( SELECT DISTINCT link.artifact_id FROM tech_assemble_detail AS link INNER JOIN tech_assemble AS m ON m.id = link.assemble_id WHERE link.bool_delete_enum = 0 AND m.bool_delete_enum = 0
AND m.area_id = #{areaId}
AND m.area_batch_id = #{areaBatchId}
AND m.serial_number like concat('%',#{assembleSerialNumber},'%') ) AS assembleDetail ON a.id = assembleDetail.artifact_id
WHERE a.bool_delete_enum = 0
and a.area_id = #{areaId}
and a.area_batch_id = #{areaBatchId}
and a.name like concat('%',#{name},'%')
and a.serial_number like concat('%',#{serialNumber},'%')
and a.specification like concat('%',#{specification},'%')
and a.material like concat('%',#{material},'%')
and a.user_names like concat('%',#{userName},'%')
AND date_format(a.create_time, '%Y-%m-%d') >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND date_format(a.create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
